function Hd = v3strong(FreqIn, Fs, Width, dbDrop, FreqPass2)
%V3STRONG Returns a discrete-time filter object.

%
% M-File generated by MATLAB(R) 7.4 and the Signal Processing Toolbox 6.7.
%
